import { api } from './api'

/**
 * Admin menu CRUD. The public `menuService` only reads the menu; this service
 * adds the write operations and the multipart upload used by the admin forms.
 *
 * `allergens` is a JSONField on the backend (see apps/menu/models.py), so the
 * list is sent JSON-encoded inside the multipart body. `slug` is generated by
 * the server and never sent from the client.
 */
export const adminMenuService = {
  /** One page of dishes. Filters: category_slug, search, is_available, ordering, page. */
  async list(params = {}) {
    const { data } = await api.get('/menu-items/', { params })
    return data
  },

  async get(id) {
    const { data } = await api.get(`/menu-items/${id}/`)
    return data
  },

  async create(payload) {
    const { data } = await api.post('/menu-items/', this.toFormData(payload))
    return data
  },

  async update(id, payload) {
    const { data } = await api.patch(`/menu-items/${id}/`, this.toFormData(payload))
    return data
  },

  async remove(id) {
    await api.delete(`/menu-items/${id}/`)
  },

  async setAvailability(id, isAvailable) {
    const { data } = await api.post(`/menu-items/${id}/set-availability/`, { is_available: isAvailable })
    return data
  },

  /**
   * Build the multipart body the backend accepts. `allergens` is a JSON array
   * of strings on the model, so it is JSON-encoded inside a single field.
   */
  toFormData(payload) {
    const form = new FormData()
    form.append('name', payload.name)
    form.append('category', String(payload.category))
    if (payload.description) form.append('description', payload.description)
    form.append('price', String(payload.price))
    if (payload.preparation_time != null) {
      form.append('preparation_time', String(payload.preparation_time))
    }
    if (payload.calories != null) form.append('calories', String(payload.calories))
    form.append('is_featured', payload.is_featured ? 'true' : 'false')
    form.append('allergens', JSON.stringify(Array.isArray(payload.allergens) ? payload.allergens : []))
    if (payload.image instanceof File) form.append('image', payload.image)
    return form
  },
}
